const form=document.getElementById("ndflForm"),result=document.getElementById("result");form&&form.addEventListener("submit",n=>{n.preventDefault();const s=parseFloat(document.getElementById("income").value)||0,i=parseFloat(document.getElementById("housing").value)||0,l=parseFloat(document.getElementById("iis").value)||0;if(s<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите доход больше нуля.</p>';return}const t=s*.13,e=Math.min(i,2e6)*.13,a=Math.min(l,4e5)*.13,o=Math.min(t,e+a);result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>НДФЛ за год (13%)</span><span class="val">${fmt(t)} ₽</span></div>
        <div class="item"><span>Возврат по имущественному</span><span class="val">${fmt(e)} ₽</span></div>
        <div class="item"><span>Возврат по ИИС</span><span class="val">${fmt(a)} ₽</span></div>
        <div class="item total"><span>К возврату (не более НДФЛ)</span><span class="val">${fmt(o)} ₽</span></div>
      </div>
    `});function fmt(n){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(n)}
